export function buildAchievementViewModel(achievements = []) {
  const r = (Array.isArray(achievements) ? achievements : []).map(item => ({ ...item, unlocked: Boolean(item?.unlocked) }));
  const unlocked = r.filter(item => item.unlocked);
  const locked = r.filter(item => !item.unlocked);
  return {
    total: r.length,
    unlockedCount: unlocked.length,
    remainingCount: locked.length,
    unlocked,
    locked
  };
}
